SC = 1.0                      # size relative to a 50-unit hero (bosses are bigger; set per build)


def import_joined(path):
    before = set(bpy.data.objects)
    bpy.ops.import_scene.gltf(filepath=path)
    obs = [o for o in bpy.data.objects if o not in before and o.type == "MESH"]
    bpy.ops.object.select_all(action="DESELECT")
    for o in obs: o.select_set(True)
    bpy.context.view_layer.objects.active = obs[0]
    if len(obs) > 1: bpy.ops.object.join()
    ob = bpy.context.view_layer.objects.active
    bpy.ops.object.parent_clear(type="CLEAR_KEEP_TRANSFORM")
    bpy.ops.object.transform_apply(location=True, rotation=True, scale=True)
    for o in [o for o in bpy.data.objects if o not in before and o.type == "EMPTY"]:
        bpy.data.objects.remove(o)
    return ob


def decimate(ob, tris):
    now = sum(len(p.vertices) - 2 for p in ob.data.polygons)
    if now > tris:
        bpy.context.view_layer.objects.active = ob
        d = ob.modifiers.new("dec", "DECIMATE")
        d.ratio = tris / now
        d.use_collapse_triangulate = True
        bpy.ops.object.modifier_apply(modifier="dec")


def vertex_colors(ob):
    """Per-vertex base colour (texture averaged over the vertex's corners)."""
    me = ob.data
    mat = me.materials[0] if me.materials else None
    tex = None
    if mat and mat.use_nodes:
        bsdf = next((n for n in mat.node_tree.nodes if n.type == "BSDF_PRINCIPLED"), None)
        if bsdf and bsdf.inputs["Base Color"].links and bsdf.inputs["Base Color"].links[0].from_node.type == "TEX_IMAGE":
            tex = bsdf.inputs["Base Color"].links[0].from_node.image
    n = len(me.vertices)
    col = np.full((n, 3), 0.5, dtype=np.float32)
    if tex is None or not me.uv_layers:
        return col
    w, h = tex.size
    px = np.empty(w * h * 4, dtype=np.float32)
    tex.pixels.foreach_get(px)
    px = px.reshape(h, w, 4)[..., :3]
    uv = np.empty(len(me.loops) * 2, dtype=np.float32)
    me.uv_layers.active.data.foreach_get("uv", uv)
    uv = uv.reshape(-1, 2)
    vi = np.empty(len(me.loops), dtype=np.int32)
    me.loops.foreach_get("vertex_index", vi)
    c = px[np.clip((uv[:, 1] % 1.0 * (h - 1)).astype(int), 0, h - 1), np.clip((uv[:, 0] % 1.0 * (w - 1)).astype(int), 0, w - 1)]
    acc = np.zeros((n, 3)); cnt = np.zeros(n)
    np.add.at(acc, vi, c); np.add.at(cnt, vi, 1)
    return (acc / np.maximum(cnt, 1)[:, None]).astype(np.float32)


def verts(ob):
    co = np.empty(len(ob.data.vertices) * 3, dtype=np.float32)
    ob.data.vertices.foreach_get("co", co)
    return co.reshape(-1, 3)


VIEWS = {   # camera side -> (image-right axis, depth axis pointing away from the camera, facing direction)
    "-Y": (np.array([1, 0, 0]), np.array([0, 1, 0]), Vector((0, -1, 0))),
    "+Y": (np.array([-1, 0, 0]), np.array([0, -1, 0]), Vector((0, 1, 0))),
    "-X": (np.array([0, -1, 0]), np.array([1, 0, 0]), Vector((-1, 0, 0))),
    "+X": (np.array([0, 1, 0]), np.array([-1, 0, 0]), Vector((1, 0, 0))),
}


def splat(P, C, right, depth, W=64, H=96):
    u = P @ right
    v = P[:, 2]
    d = P @ depth
    u0, u1, v0, v1 = u.min(), u.max(), v.min(), v.max()
    s = min((W - 1) / (u1 - u0), (H - 1) / (v1 - v0))
    iu = ((u - u0) * s).astype(int)
    iv = ((v1 - v) * s).astype(int)
    img = np.zeros((H, W, 3), np.float32)
    zb = np.full((H, W), np.inf)
    order = np.argsort(-d)          # far first, near overwrite
    for k in order:
        img[iv[k], iu[k]] = C[k]
        zb[iv[k], iu[k]] = d[k]
    return img, np.isfinite(zb)


def load_painting_small(path, bbox, W=64, H=96):
    """The painting's figure, cropped to the silhouette box and scaled like the splat (numpy only:
    loaded through Blender's image API)."""
    im = bpy.data.images.load(path)
    w, h = im.size
    px = np.empty(w * h * 4, dtype=np.float32)
    im.pixels.foreach_get(px)
    px = px.reshape(h, w, 4)[::-1, :, :3]             # Blender stores bottom-up
    x0, y0, x1, y1 = bbox
    crop = px[y0:y1 + 1, x0:x1 + 1]
    ch, cw = crop.shape[:2]
    s = min((W - 1) / cw, (H - 1) / ch)
    out = np.zeros((H, W, 3), np.float32)
    ys = np.clip((np.arange(H) / s).astype(int), 0, ch - 1)
    xs = np.clip((np.arange(W) / s).astype(int), 0, cw - 1)
    out[:, :] = crop[ys][:, xs]
    bpy.data.images.remove(im)
    return out


def best_facing(ob, painting_small):
    P = verts(ob)
    C = vertex_colors(ob)
    scores = {}
    for name, (right, depth, face) in VIEWS.items():
        img, mask = splat(P, C, right, depth)
        a = img[mask].mean(axis=1)
        b = painting_small[mask].mean(axis=1)
        if len(a) < 50:
            scores[name] = -1.0
            continue
        scores[name] = float(np.corrcoef(a, b)[0, 1])
        if os.environ.get("SPLAT_DEBUG"):
            im = bpy.data.images.new(f"splat_{name}", img.shape[1], img.shape[0])
            rgba = np.concatenate([img[::-1], np.ones(img.shape[:2] + (1,), np.float32)], axis=2)
            im.pixels.foreach_set(rgba.ravel())
            im.filepath_raw = os.path.join(os.environ["SPLAT_DEBUG"], f"splat_{name}.png"); im.file_format = "PNG"; im.save()
    best = max(scores, key=scores.get)
    print("FACING", {k: round(v, 3) for k, v in scores.items()}, "->", best)
    return VIEWS[best][2]


def face_plus_x(ob, facing):
    ang = math.atan2(facing.y, facing.x)
    ob.data.transform(Matrix.Rotation(-ang, 4, "Z"))


def fit_joints(ob, pose):
    """Map the painting's joints onto the mesh (now facing +X, image right = +Y = character's left)."""
    P = verts(ob)
    ylo, yhi, zlo, zhi = P[:, 1].min(), P[:, 1].max(), P[:, 2].min(), P[:, 2].max()
    x0, y0, x1, y1 = pose["bbox"]
    # Mesh units per pixel from the HEIGHT: a cape spread on the floor widens the mesh and the box
    # differently, and the width-based scale fitted the Warden's skeleton 20% too big (critique pass 2).
    s = (zhi - zlo) / max(1, (y1 - y0))
    jn = pose["joints"]
    sh_px = (jn["l_sh"][0] + jn["r_sh"][0]) / 2
    sh_z = zlo + (y1 - (jn["l_sh"][1] + jn["r_sh"][1]) / 2) * s
    band = np.abs(P[:, 2] - (sh_z - 0.06 * (zhi - zlo))) < 0.02 * (zhi - zlo)
    y_mid = float(np.median(P[band, 1])) if band.sum() > 10 else float((ylo + yhi) / 2)
    def to_mesh(px, py):
        return y_mid + (px - sh_px) * s, zlo + (y1 - py) * s
    J2 = {k: to_mesh(v[0], v[1]) for k, v in pose["joints"].items()}
    def depth_at(y, z, r):
        sel = (np.abs(P[:, 1] - y) < r) & (np.abs(P[:, 2] - z) < r)
        if sel.sum() < 6:
            return float(np.median(P[:, 0]))
        xs = P[sel, 0]
        return float((np.percentile(xs, 5) + np.percentile(xs, 95)) / 2)
    H = zhi - zlo
    J = {}
    def put(name, key_or_yz, r=0.03):
        y, z = J2[key_or_yz] if isinstance(key_or_yz, str) else key_or_yz
        J[name] = Vector((depth_at(y, z, r * H), y, z))
    mid = lambda a, b: ((J2[a][0] + J2[b][0]) / 2, (J2[a][1] + J2[b][1]) / 2)
    put("shoulder.L", "l_sh"); put("shoulder.R", "r_sh")
    put("elbow.L", "l_el"); put("elbow.R", "r_el")
    put("wrist.L", "l_wr"); put("wrist.R", "r_wr")
    put("hip.L", "l_hip"); put("hip.R", "r_hip")
    put("knee.L", "l_kn"); put("knee.R", "r_kn")
    put("ankle.L", "l_an"); put("ankle.R", "r_an")
    hy, hz = mid("l_hip", "r_hip")
    sy, sz = mid("l_sh", "r_sh")
    ny, nz = J2["nose"]
    put("pelvis", (hy, hz + 0.02 * H), 0.05)
    put("neck", (sy, sz + 0.035 * H), 0.04)
    put("head", (ny, nz - 0.01 * H), 0.05)
    for name, k in (("spine", 0.3), ("chest", 0.62), ("collar", 0.86)):
        put(name, (hy + (sy - hy) * k, hz + (sz - hz) * k), 0.05)
    J["top"] = J["head"] + Vector((0, 0, 0.11 * H))
    for sd in ("L", "R"):
        d = (J[f"wrist.{sd}"] - J[f"elbow.{sd}"]).normalized()
        J[f"hand.{sd}"] = J[f"wrist.{sd}"] + d * 0.05 * H
        J[f"toe.{sd}"] = Vector((J[f"ankle.{sd}"].x + 0.07 * H, J[f"ankle.{sd}"].y, zlo + 0.014 * H))
        J[f"ankle.{sd}"].z = max(J[f"ankle.{sd}"].z, zlo + 0.03 * H)
    return J


def normalize(ob, J):
    """Scale so nose-to-ankle matches the game's heroes, feet on 0, centred over the pelvis."""
    ankle_z = (J["ankle.L"].z + J["ankle.R"].z) / 2
    k = NOSE_TO_ANKLE * SC / max(1e-4, J["head"].z - ankle_z)
    zlo = verts(ob)[:, 2].min()
    T = Matrix.Scale(k, 4) @ Matrix.Translation((-J["pelvis"].x, -J["pelvis"].y, -zlo))
    ob.data.transform(T)
    for n in J:
        J[n] = T @ J[n]
    return k


def skeleton(J):
    s = 1.0
    bones = [("root", Vector((0, 0, 0)), Vector((0, 0, 6)), None),
             ("hips", J["pelvis"], J["spine"], "root"), ("spine", J["spine"], J["chest"], "hips"),
             ("chest", J["chest"], J["neck"], "spine"), ("neck", J["neck"], J["head"], "chest"),
             ("head", J["head"], J["top"], "neck")]
    for sd in ("L", "R"):
        bones += [(f"upperarm.{sd}", J[f"shoulder.{sd}"], J[f"elbow.{sd}"], "chest"),
                  (f"forearm.{sd}", J[f"elbow.{sd}"], J[f"wrist.{sd}"], f"upperarm.{sd}"),
                  (f"hand.{sd}", J[f"wrist.{sd}"], J[f"hand.{sd}"], f"forearm.{sd}"),
                  (f"thigh.{sd}", J[f"hip.{sd}"], J[f"knee.{sd}"], "hips"),
                  (f"shin.{sd}", J[f"knee.{sd}"], J[f"ankle.{sd}"], f"thigh.{sd}"),
                  (f"foot.{sd}", J[f"ankle.{sd}"], J[f"toe.{sd}"], f"shin.{sd}")]
    c0 = J["collar"] + Vector((-4.0, 0, 0.6)) * SC
    bones += [("cape1", c0, c0 + Vector((-0.6, 0, -9)) * SC, "chest"),
              ("cape2", c0 + Vector((-0.6, 0, -9)) * SC, c0 + Vector((-1.0, 0, -18)) * SC, "cape1"),
              ("cape3", c0 + Vector((-1.0, 0, -18)) * SC, c0 + Vector((-1.2, 0, -27)) * SC, "cape2")]
    return bones


def seg_dist(P, a, b):
    a = np.array(a); b = np.array(b)
    ab = b - a
    t = np.clip(((P - a) @ ab) / max(1e-6, ab @ ab), 0, 1)
    return np.linalg.norm(P - (a + t[:, None] * ab), axis=1)


def bind_body(rig, ob, deform_names):
    """Heat weights computed on a watertight voxel-remeshed proxy (generated meshes have holes and
    overlapping shells, where Blender's heat solver fails), then transferred to the real mesh by
    nearest surface. Vertices still unweighted get inverse-distance weights to the nearest bones."""
    for b in rig.ob.data.bones:
        b.use_deform = b.name in deform_names
    proxy = ob.copy(); proxy.data = ob.data.copy(); proxy.name = "weight_proxy"
    bpy.context.scene.collection.objects.link(proxy)
    for g in list(proxy.vertex_groups): proxy.vertex_groups.remove(g)
    bpy.context.view_layer.objects.active = proxy
    rm = proxy.modifiers.new("remesh", "REMESH")
    rm.mode = "VOXEL"
    rm.voxel_size = 0.55 * SC
    rm.use_smooth_shade = True
    bpy.ops.object.modifier_apply(modifier="remesh")
    bpy.ops.object.select_all(action="DESELECT")
    proxy.select_set(True); rig.ob.select_set(True)
    bpy.context.view_layer.objects.active = rig.ob
    bpy.ops.object.parent_set(type="ARMATURE_AUTO")
    pw = sum(1 for v in proxy.data.vertices if v.groups)
    print(f"PROXY {len(proxy.data.vertices)} verts, heat-weighted {pw}")
    if pw < 0.95 * len(proxy.data.vertices):
        # the heat solver gave up on some or all bones: distance weights for what it missed, then smoothed
        # over the surface so joints bend instead of creasing
        PP = verts(proxy)
        miss = [v.index for v in proxy.data.vertices if not v.groups]
        segs = {b.name: (b.head_local, b.tail_local) for b in rig.ob.data.bones if b.name in deform_names}
        names = list(segs)
        D = np.stack([seg_dist(PP[miss], *segs[n]) for n in names], axis=1)
        for g in names:
            if proxy.vertex_groups.get(g) is None: proxy.vertex_groups.new(name=g)
        for row, vi in enumerate(miss):
            idx = np.argsort(D[row])[:3]
            w = 1.0 / np.maximum(D[row, idx], 0.3) ** 4
            w /= w.sum()
            for j, wt in zip(idx, w):
                if wt > 0.02: proxy.vertex_groups[names[j]].add([vi], float(wt), "REPLACE")
        bpy.context.view_layer.objects.active = proxy
        bpy.ops.object.select_all(action="DESELECT"); proxy.select_set(True)
        bpy.ops.object.mode_set(mode="WEIGHT_PAINT")
        bpy.ops.object.vertex_group_smooth(group_select_mode="ALL", factor=0.5, repeat=6, expand=0.0)
        bpy.ops.object.vertex_group_normalize_all(lock_active=False)
        bpy.ops.object.mode_set(mode="OBJECT")
        print(f"PROXY distance weights for {len(miss)} vertices, smoothed")
    # proxy -> real mesh
    for g in list(ob.vertex_groups): ob.vertex_groups.remove(g)
    for g in proxy.vertex_groups: ob.vertex_groups.new(name=g.name)
    dt = ob.modifiers.new("dt", "DATA_TRANSFER")
    dt.object = proxy
    dt.use_vert_data = True
    dt.data_types_verts = {"VGROUP_WEIGHTS"}
    dt.vert_mapping = "POLYINTERP_NEAREST"
    dt.layers_vgroup_select_src = "ALL"
    dt.layers_vgroup_select_dst = "NAME"
    bpy.context.view_layer.objects.active = ob
    bpy.ops.object.datalayout_transfer(modifier="dt")
    bpy.ops.object.modifier_apply(modifier="dt")
    bpy.data.objects.remove(proxy)
    for b in rig.ob.data.bones:
        b.use_deform = True
    ob.parent = rig.ob
    am = ob.modifiers.get("Armature") or ob.modifiers.new("Armature", "ARMATURE")
    am.object = rig.ob
    P = verts(ob)
    total = np.zeros(len(P))
    for v in ob.data.vertices:
        total[v.index] = sum(g.weight for g in v.groups)
    miss = np.where(total < 0.05)[0]
    if len(miss):
        segs = {b.name: (b.head_local, b.tail_local) for b in rig.ob.data.bones if b.name in deform_names}
        D = np.stack([seg_dist(P[miss], *segs[n]) for n in segs], axis=1)
        names = list(segs)
        for row, vi in enumerate(miss):
            idx = np.argsort(D[row])[:2]
            w = 1.0 / np.maximum(D[row, idx], 0.05) ** 4
            w /= w.sum()
            for j, wt in zip(idx, w):
                g = ob.vertex_groups.get(names[j]) or ob.vertex_groups.new(name=names[j])
                g.add([int(vi)], float(wt), "REPLACE")
    print(f"WEIGHTS transferred to {len(P) - len(miss)}/{len(P)} vertices, nearest-bone fallback for {len(miss)}")


def cloth_weights(ob, J):
    """Robes, tabards and capes: automatic weights tie cloth between and behind the legs to the thighs,
    so a stride tore it into a horizontal sheet (critique pass 1). Cloth below the hips that is not
    inside a leg follows the hips with a little of the near thigh; cloth behind the back follows the
    torso by height and never the legs."""
    P = verts(ob)
    hip_z = (J["hip.L"].z + J["hip.R"].z) / 2
    knee_z = (J["knee.L"].z + J["knee.R"].z) / 2
    back_x = min(J["spine"].x, J["pelvis"].x) - 3.2 * SC
    leg_r = 4.2 * SC         # armoured shins and fur boots are thick: only cloth well outside the leg counts
    arm_r = 3.6 * SC
    legs = {sd: [(J[f"hip.{sd}"], J[f"knee.{sd}"]), (J[f"knee.{sd}"], J[f"ankle.{sd}"])] for sd in ("L", "R")}
    dleg = {sd: np.minimum(seg_dist(P, *legs[sd][0]), seg_dist(P, *legs[sd][1])) for sd in ("L", "R")}
    darm = np.min(np.stack([seg_dist(P, J[f"{a}.{sd}"], J[f"{b}.{sd}"]) for sd in ("L", "R")
                            for a, b in (("shoulder", "elbow"), ("elbow", "wrist"), ("wrist", "hand"))]), axis=0)
    near_limb = (np.minimum(dleg["L"], dleg["R"]) < leg_r) | (darm < arm_r)
    groups = {g.name: g for g in ob.vertex_groups}
    def need(n): return groups.get(n) or groups.setdefault(n, ob.vertex_groups.new(name=n))
    n_skirt = n_cape = 0
    for v in ob.data.vertices:
        x, y, z = P[v.index]
        w = None
        if near_limb[v.index]:
            continue
        if x < back_x and z > knee_z - 4.0 and z < J["neck"].z:
            # cape: chest at the shoulders sliding to hips toward the hem
            k = min(1.0, max(0.0, (J["chest"].z - z) / max(1.0, J["chest"].z - knee_z)))
            w = {"chest": 1.0 - k, "spine": 0.5 * k, "hips": 0.5 * k}
            n_cape += 1
        elif z < hip_z - 1.0:
            k = min(1.0, max(0.0, (hip_z - z) / max(1.0, hip_z - knee_z * 0.5)))
            side = "thigh.L" if y > 0 else "thigh.R"
            tw = k * 0.3
            w = {"hips": 1.0 - tw, side: tw}
            n_skirt += 1
        if w is None:
            continue
        for g in v.groups:
            ob.vertex_groups[g.group].remove([v.index])
        for n, wt in w.items():
            if wt > 0.01: need(n).add([v.index], float(wt), "REPLACE")
    print(f"CLOTH skirt {n_skirt}, cape {n_cape} vertices reweighted")


def place_weapon(path, kind, J, hero_h=50.0):
    """A TRELLIS weapon mesh, stood up by its shape and moved to the hand. Returns (object, bone)."""
    ob = import_joined(path)
    decimate(ob, 3500)
    P = verts(ob)
    ext = P.max(0) - P.min(0)
    ax = int(np.argmax(ext))
    # long axis -> +Z
    if ax == 0: ob.data.transform(Matrix.Rotation(math.pi / 2, 4, "Y"))
    elif ax == 1: ob.data.transform(Matrix.Rotation(-math.pi / 2, 4, "X"))
    P = verts(ob)
    z0, z1 = P[:, 2].min(), P[:, 2].max()
    def width_at(k):
        sel = (P[:, 2] - z0) / (z1 - z0)
        sel = (sel > k - 0.06) & (sel < k + 0.06)
        if sel.sum() < 3: return 0.0
        q = P[sel][:, :2]
        return float(np.linalg.norm(q.max(0) - q.min(0)))
    if kind == "shield":
        # thinnest horizontal axis becomes the face normal, pointing out of the left arm (+Y)
        e = P.max(0) - P.min(0)
        if e[0] < e[1]: ob.data.transform(Matrix.Rotation(math.pi / 2, 4, "Z"))
        P = verts(ob)
        k = 17.0 / (P[:, 2].max() - P[:, 2].min())
        c = (P.max(0) + P.min(0)) / 2
        fl = J["wrist.L"].lerp(J["elbow.L"], 0.45)
        ob.data.transform(Matrix.Translation(fl + Vector((0.6, 3.0, -1.0))) @ Matrix.Scale(k, 4) @ Matrix.Translation(Vector(-c)))
        return ob, "forearm.L"
    head_top = width_at(0.9) >= width_at(0.1)
    if kind == "staff":
        if not head_top: ob.data.transform(Matrix.Rotation(math.pi, 4, "X"))
        P = verts(ob)
        L = P[:, 2].max() - P[:, 2].min()
        k = 54.0 * SC / L
        c = (P.max(0) + P.min(0)) / 2
        hand = J["hand.R"]
        # base near the ground, grip in the hand: shift so the shaft passes through the hand
        T = Matrix.Translation(Vector((hand.x + 0.3, hand.y, 0.0))) @ Matrix.Scale(k, 4) @ Matrix.Translation(Vector((-c[0], -c[1], -P[:, 2].min())))
        ob.data.transform(T)
        return ob, "hand.R"
    # sword: the crossguard is the widest section. Put the hilt end up, grip just above the guard in the
    # hand, blade pointing down and forward like the procedural Warden's.
    prof = [width_at(k) for k in np.linspace(0.05, 0.95, 19)]
    gk = 0.05 + 0.05 * int(np.argmax(prof))
    if gk < 0.5:
        ob.data.transform(Matrix.Rotation(math.pi, 4, "X"))
        P = verts(ob); z0, z1 = P[:, 2].min(), P[:, 2].max(); gk = 1.0 - gk
    L = z1 - z0
    k = 30.0 / L
    c = (P.max(0) + P.min(0)) / 2
    grip = Vector((c[0], c[1], z0 + min(0.98, gk + 0.06) * L))
    blade = Vector((0.35, 0, -1)).normalized()
    q = Vector((0, 0, 1)).rotation_difference(-blade).to_matrix().to_4x4()
    ob.data.transform(Matrix.Translation(J["hand.R"]) @ q @ Matrix.Scale(k, 4) @ Matrix.Translation(-grip))
    return ob, "hand.R"


def build(hero, cfg, gen):
    global SC
    SC = float(cfg.get("scale", 1.0))
    B.reset()
    pose = json.load(open(os.path.join(gen, cfg["concept"] + "_pose.json")))
    ob = import_joined(os.path.join(gen, hero + ".glb"))
    decimate(ob, cfg["tris"])
    painting = load_painting_small(os.path.join(gen, cfg["concept"] + ".jpg"), pose["bbox"])
    # TRELLIS follows glTF (front +Z = Blender -Y). The splat comparison is logged as a check only:
    # on noisy point splats it picked the back of the Sparkcaller over its front (critique pass 1).
    best_facing(ob, painting)
    face_plus_x(ob, VIEWS["-Y"][2])
    J = fit_joints(ob, pose)
    normalize(ob, J)
    rig = B.Rig(hero, skeleton(J))
    deform = [b.name for b in rig.ob.data.bones if not b.name.startswith("cape") and b.name != "root"]
    bind_body(rig, ob, deform)
    cloth_weights(ob, J)
    for wname, kind in cfg["weapons"]:
        wob, bone = place_weapon(os.path.join(gen, wname + ".glb"), kind, J)
        g = wob.vertex_groups.new(name=bone)
        g.add(list(range(len(wob.data.vertices))), 1.0, "REPLACE")
        wob.parent = rig.ob
        m = wob.modifiers.new("Armature", "ARMATURE"); m.object = rig.ob
    # A-pose arms down to the clips' rest (about 0.14 rad out from the body)
    for sd, sign in (("L", 1.0), ("R", -1.0)):
        d = J[f"elbow.{sd}"] - J[f"shoulder.{sd}"]
        out = math.atan2(abs(d.y), -d.z)
        rig.base[f"upperarm.{sd}"] = (-sign * (out - 0.14), 0.0, 0.0)
    packs = PACKS
    if packs:
        src, src_obs = RT.load_source(os.path.join(packs, KK_SRC))
        clips = CLIPS_BOSS if cfg.get("boss") else (CLIPS_MELEE if hero == "warden" else CLIPS_CASTER)
        strides = RT.retarget(rig, src, clips, cape_fns())
        for o in src_obs: bpy.data.objects.remove(o)
        print(f"STRIDES {hero}: " + ", ".join(f"{n} {v:.1f}" for n, v in strides.items() if n in ("walk", "run")))
    elif cfg.get("boss"):
        B.boss_clips(rig, SC, heavy=1.2)                 # idle, walk, attack (wind-up, slam), hit, die
    else:
        B.hero_clips(rig, "R", s=1.0, stride=0.55)      # long robes and capes read better with a shorter stride
    path = os.path.join(MODELS, "bosses" if cfg.get("boss") else "heroes", hero + ".gltf")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    bpy.ops.object.select_all(action="DESELECT")
    rig.ob.select_set(True)
    for c in rig.ob.children: c.select_set(True)
    bpy.ops.export_scene.gltf(
        filepath=path, export_format="GLTF_SEPARATE", export_texture_dir=f"{hero}_tex", use_selection=True,
        export_yup=True, export_apply=False, export_animations=True, export_animation_mode="NLA_TRACKS",
        export_force_sampling=True, export_frame_step=1, export_def_bones=False, export_skins=True,
        export_image_format="JPEG", export_image_quality=88, export_materials="EXPORT")
    tris = sum(sum(len(p.vertices) - 2 for p in c.data.polygons) for c in rig.ob.children if c.type == "MESH")
    print(f"HERO {hero}: {tris} tris, arm offsets L {rig.base['upperarm.L'][0]:.2f} R {rig.base['upperarm.R'][0]:.2f} -> {path}")


PACKS = ""

if __name__ == "__main__":
    argv = sys.argv[sys.argv.index("--") + 1:] if "--" in sys.argv else []
    if "--packs" in argv:
        PACKS = argv[argv.index("--packs") + 1]
        del argv[argv.index("--packs"):argv.index("--packs") + 2]
    if "--out" in argv:                    # build somewhere else (to compare against the shipped models)
        MODELS = argv[argv.index("--out") + 1]
        del argv[argv.index("--out"):argv.index("--out") + 2]
    gen = argv[0]
    for h in (argv[1:] or list(HEROES)):
        build(h, HEROES[h], gen)
